async page => {
  const out = 'C:/Users/sj930/Documents/Codex/2026-10-22/kfcoding-aihub-ooioo-fluxionai-users-shenjian/outputs/playwright/platform-scope/';
  const errors = [], blocked = [], results = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.unroute('**/*');
  await page.route('**/*', route => {
    const u = new URL(route.request().url());
    if (u.hostname === '127.0.0.1' && u.port === '8767') return route.continue();
    blocked.push(u.origin + u.pathname); return route.abort('blockedbyclient');
  });
  const ref = name => page.locator('[data-ref="'+name+'"]');
  const check = (value, message) => { if (!value) throw Error(message); };
  const counters = () => page.evaluate(() => [localEvidence.requests.length, localEvidence.configWrites, localEvidence.modelCalls, localEvidence.groupWrites.length]);
  const same = async (before, message) => check(JSON.stringify(await counters()) === JSON.stringify(before), message);
  for (const width of [1360,390,320]) for (const theme of ['dark','light']) {
    await page.setViewportSize({width,height:1000});
    await page.emulateMedia({colorScheme:theme,reducedMotion:width===320?'reduce':'no-preference'});
    await page.goto('http://127.0.0.1:8767/v022.html?site=aihub&pelican&platforms&scopepersist&case='+Date.now()+'&theme='+theme);
    await ref('check').click();
    await ref('candidateRows').locator('.candidate').first().waitFor();
    check(await ref('candidateRows').locator('.candidate').count()===40,'full candidates preserved');
    let before=await counters();
    for (const [platform,count] of [['openai',7],['deepseek',7],['zhipu',7],['kimi',7],['grok',6],['unknown',6]]) {
      const scopeBefore = await counters();
      await ref('candidatePlatform').selectOption(platform);
      const scopeAfter = await counters();
      check(scopeAfter[0]===scopeBefore[0]&&scopeAfter[1]===scopeBefore[1]+1&&scopeAfter[2]===scopeBefore[2]&&scopeAfter[3]===scopeBefore[3],'scope save has exactly one config write and zero requests/inference/group writes');
      check(await ref('candidateRows').locator('.candidate').count()===0,'old decision rows retired');
      await ref('check').click();
      await ref('candidateRows').locator('.candidate').first().waitFor();
      check(await ref('candidateRows').locator('.candidate').count()===count+(platform==='openai'?0:1),'only scoped plus current health rows evaluated');
      check(await ref('candidateRows').locator('.candidate:not([hidden])').count()===count,'monitor '+platform);
      if(platform!=='openai') check(await ref('candidateRows').locator('.candidate[hidden]').first().isHidden(),'outside current health row must actually be invisible');
    }
    await ref('candidatePlatform').selectOption('kimi');
    await page.reload();
    check(await ref('candidatePlatform').inputValue()==='kimi','business scope restored on reload');
    await ref('check').click();
    await ref('candidateRows').locator('.candidate').first().waitFor();
    before = await counters();
    await ref('candidateSearch').fill('04');
    check(await ref('candidateRows').locator('.candidate:not([hidden])').count()===1,'combined monitor search');
    await ref('candidateSearch').fill('openai');
    check(await ref('candidateRows').locator('.candidate:not([hidden])').count()===0,'cross-platform query excluded');
    check((await ref('candidateSearchStatus').innerText()).includes('无匹配'),'monitor empty status');
    await ref('candidateSearch').press('Escape');
    await same(before,'monitor search has no IO/config effects');
    await ref('candidatePlatform').selectOption('');
    await ref('candidatePlatform').focus();
    await ref('candidatePlatform').press('ArrowDown'); await ref('candidatePlatform').press('Enter');
    check(await ref('candidatePlatform').inputValue()==='openai','native keyboard selection');
    await ref('candidatePlatform').press('Escape');
    check((await page.evaluate(()=>localEvidence.config.businessPlatform))==='openai','keyboard scope saves business setting');
    await ref('check').click();
    await ref('candidateRows').locator('.candidate').first().waitFor();
    await page.screenshot({path:out+'monitor-'+width+'-'+theme+'.png'});
    await page.locator('#kf-tab-settings').click();
    await page.locator('[data-settings-target=routing]').click();
    await ref('groupFilterSelectToggle').click();
    await ref('groupFilterList').locator('input[data-group-name="kimi-04"]').check();
    before=await counters();
    await ref('groupFilterPlatform').selectOption('openai');
    check(await ref('groupFilterList').locator('.token-option:not([hidden])').count()===7,'whitelist platform');
    check(await ref('groupFilterList').locator('input[data-group-name="kimi-04"]').isChecked(),'hidden whitelist checked');
    await ref('groupFilterSearch').fill('04');
    check(await ref('groupFilterList').locator('.token-option:not([hidden])').count()===0,'whitelist intersection');
    await same(before,'whitelist filter changes IO/config');
    await ref('groupFilterSearch').press('Escape');await ref('groupFilterSearch').press('Escape');
    await ref('groupFilterMode').selectOption('blacklist');
    await ref('groupFilterSelectToggle').click();
    before=await counters();
    await ref('groupFilterPlatform').selectOption('unknown');
    check(await ref('groupFilterList').locator('.token-option:not([hidden])').count()===6,'blacklist unknown');
    await same(before,'blacklist filter changes IO/config');
    await ref('groupFilterSearch').press('Escape');
    await page.locator('[data-settings-target=quality]').click();
    await page.locator('details').filter({has:ref('imageQualityFallback1Search')}).locator('summary').click();
    before=await counters();
    for (const n of [1,2]) {
      const name='imageQualityFallback'+n;
      await ref(name+'Platform').selectOption('grok');
      check(await ref(name).inputValue()===String(n+1),'fallback selected retained');
      check(await ref(name).locator('option').count()===8,'six matches plus neutral/current');
      await ref(name+'Search').fill('no such group');
      check(await ref(name).locator('option').count()===2,'empty preserves neutral/current');
      check((await ref(name+'SearchStatus').innerText()).includes('无匹配'),'fallback empty');
      await ref(name+'Search').press('Escape');
      await ref(name+'Platform').selectOption('unknown');
      check(await ref(name).locator('option').count()===8,'fallback unknown');
    }
    await same(before,'quality filter triggers inference/group/config');
    await page.screenshot({path:out+'fallback-'+width+'-'+theme+'.png'});
    await page.locator('#kf-tab-monitor').click();
    await ref('manualSwitch').click();
    await ref('manualGroup').locator('input[data-manual-group="kimi-04"]').check();
    before=await counters();
    await ref('manualGroupPlatform').selectOption('deepseek');
    check(await ref('manualGroup').locator('.manual-group-option:not([hidden])').count()===7,'manual platform');
    check(await ref('manualGroup').locator('input[data-manual-group="kimi-04"]').isChecked(),'hidden radio retained');
    check(await ref('manualConfirm').isEnabled(),'hidden selection confirmable');
    await ref('manualGroupSearch').fill('02');
    check(await ref('manualGroup').locator('.manual-group-option:not([hidden])').count()===1,'manual intersection');
    await ref('manualGroupSearch').press('ArrowDown');
    check(await ref('manualGroup').locator('input[data-manual-group="deepseek-02"]').evaluate(e=>e.getRootNode().activeElement===e),'keyboard focuses visible choice');
    await ref('manualGroupSearch').fill('no such group');
    check((await ref('manualGroupSearchStatus').innerText()).includes('无匹配'),'manual empty');
    await same(before,'manual filters trigger switch/requests');
    await page.screenshot({path:out+'manual-'+width+'-'+theme+'.png'});
    check(await ref('manualDialog').evaluate(e=>e.scrollWidth<=e.clientWidth+1),'manual horizontal overflow');
    await ref('manualCancel').click();
    results.push({width,theme,reducedMotion:width===320,counters:await counters()});
  }
  const final=await counters();
  check(final[2]===0&&final[3]===0,'no inference or business writes');
  check(errors.length===0,'uncaught errors: '+errors.join(';'));
  const report={results,errors,blocked,final,environment:'real Chromium interaction; loopback mocked IO; no live AIHub/paid calls'};
  return report;
}
